(async function(){try{let store=SiteData;try{if(parent!==window&&parent.SiteData)store=parent.SiteData;}catch{}const p=new URLSearchParams(location.hash.slice(1)),r=await store.getRun(p.get('id')),target=p.get('target')||'Cost_sum',i=Number(p.get('sample')||0),t=r.targets[target];if(!t||!Number.isInteger(i)||i<0||i>=r.rows.length)throw Error('局部方案不存在。');const f={};r.features.forEach((field,j)=>{if(t.shap[i][j]!==0)f[j]={effect:t.shap[i][j],value:r.rows[i].features[field.key]};});const data={outNames:[t.label],baseValue:t.base_value,outValue:t.predicted[i],link:'identity',featureNames:r.features.map(f=>f.label),features:f,plot_cmap:'RdBu',labelMargin:20};SHAP.ReactDom.render(SHAP.React.createElement(SHAP.AdditiveForceVisualizer,data),document.getElementById('force'));}catch(e){document.getElementById('force').className='error';document.getElementById('force').textContent=e.message;}})();
